#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;
int main() {
    long long n;
    scanf("%lld", &n);
    // First outer pair: 6 ordered colorings, each next pair inward: 3.
    long long result = 6, base = 3, e = n / 2 - 1;
    while (e > 0) {
        if (e & 1) result = result * base % MOD;
        base = base * base % MOD;
        e >>= 1;
    }
    printf("%lld\n", result);
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        long n = new Scanner(System.in).nextLong();
        BigInteger mod = BigInteger.valueOf(1000000007);
        // First outer pair: 6 ordered colorings, each next pair inward: 3.
        BigInteger r = BigInteger.valueOf(3).modPow(BigInteger.valueOf(n / 2 - 1), mod).multiply(BigInteger.valueOf(6)).mod(mod);
        System.out.println(r);
    }
}

